package gr.argyrismitsos.fleetserver;
import android.content.*;import android.net.Uri;import android.database.sqlite.SQLiteDatabase;
import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;

/** Portable recovery controller. Complete private preparation precedes an explicit cold restart. */
public final class NativeRecoveryController {
    private static final String PREVIEW="primary.recovery.preview",ALIAS="fleet.primary.recovery.preview.v1",STATUS="native_recovery_status";
    private static final AtomicBoolean running=new AtomicBoolean();
    private NativeRecoveryController(){}
    private static SharedPreferences prefs(Context c){return c.getSharedPreferences(BackupManager.PREFS,Context.MODE_PRIVATE);}
    private static void stage(Context c,String label)throws Exception{if(Thread.currentThread().isInterrupted()||OtaManager.shouldYieldForUpdate(c))throw new InterruptedIOException("Η ανάκτηση σταμάτησε με ασφάλεια πριν ολοκληρωθεί. Επανάλαβε από αυτή την οθόνη.");prefs(c).edit().putString(STATUS,new JSONObject().put("stage",label).put("updatedAt",System.currentTimeMillis()).toString()).apply();ServerWorkTracker.stage("action:primaryRecovery","Ανάκτηση Server",label);}
    private static void copy(File source,File destination)throws Exception{File parent=destination.getParentFile();if(!parent.exists()&&!parent.mkdirs())throw new IOException("Δεν δημιουργήθηκε ο χώρος ανάκτησης.");try(InputStream input=new BufferedInputStream(new FileInputStream(source));FileOutputStream output=new FileOutputStream(destination)){byte[] buffer=new byte[65536];int n;while((n=input.read(buffer))!=-1)output.write(buffer,0,n);output.getFD().sync();}}
    public static JSONObject preview(final Context c,Uri uri,String password)throws Exception{
        if(!running.compareAndSet(false,true))throw new IOException("Εκτελείται ήδη προετοιμασία ανάκτησης.");
        try{
            JSONObject existing=NativeColdRuntime.core(c).state();if(!Arrays.asList("","installed","failed").contains(existing.optString("phase")))throw new IOException("Υπάρχει ήδη προετοιμασμένη ανάκτηση. Επανεκκίνησε για να συνεχιστεί.");
            stage(c,"Άνοιγμα και έλεγχος πλήρους φορητού backup");JSONObject root=BackupManager.readBackupRoot(c,uri,password);if(!NativeBackupReader.isNative(root))throw new IOException("Για αυτό το παλιότερο αντίγραφο χρησιμοποίησε την επαναφορά παλιού backup.");
            String id=UUID.randomUUID().toString();final File directory=NativeColdRuntime.core(c).directory(id);
            try(NativeBackupReader.Prepared prepared=BackupManager.readNative(c,uri,root,password)){
                long needed=prepared.database.length()*3+32L*1024*1024;JSONArray objects=prepared.manifest.getJSONArray("objects");for(int i=0;i<objects.length();i++)needed+=objects.getJSONObject(i).getLong("size")*3;
                if(c.getFilesDir().getUsableSpace()<needed)throw new IOException("Δεν υπάρχει αρκετός χώρος για ασφαλή ανάκτηση και διατήρηση των προηγούμενων αρχείων.");
                stage(c,"Πραγματική απομονωμένη δοκιμή βάσης και ιδιωτικών αρχείων");JSONObject proof=NativeBackupRestoreProbe.run(c,prepared.database,prepared.manifest,prepared.documents);if(!proof.optBoolean("restoreVerified")||!proof.optBoolean("documentsVerified"))throw new IOException("Δεν επαληθεύτηκε πλήρης ανάκτηση.");
                JSONArray accounts;SQLiteDatabase database=SQLiteDatabase.openDatabase(prepared.database.getPath(),null,SQLiteDatabase.OPEN_READONLY);try{accounts=new BusinessSqlite(database).call("sql.query",new JSONObject().put("sql","SELECT id,full_name,username,role,active,login_enabled,deleted_at FROM app_users ORDER BY role,full_name,id")).getJSONArray("results");}finally{database.close();}
                boolean owner=false;for(int i=0;i<accounts.length();i++){JSONObject account=accounts.getJSONObject(i);if(account.optString("role").equals("owner")&&account.optInt("active")==1&&account.optInt("login_enabled")==1&&account.isNull("deleted_at"))owner=true;}if(!owner)throw new IOException("Το backup δεν περιέχει ενεργό λογαριασμό ιδιοκτήτη. Δεν μπορεί να ενεργοποιηθεί ως κύρια βάση.");
                stage(c,"Προετοιμασία επαληθευμένων αρχείων για την επόμενη εκκίνηση");copy(prepared.database,new File(directory,"new-databases/"+NativeColdRestore.DATABASE_NAME));File newDocs=new File(directory,"new-documents");if(!newDocs.mkdirs())throw new IOException("Δεν δημιουργήθηκε ο χώρος ιδιωτικών αρχείων ανάκτησης.");
                if(prepared.documents!=null){Context isolated=new ContextWrapper(c){@Override public File getFilesDir(){return directory;}@Override public File getCacheDir(){File file=new File(directory,"cache");file.mkdirs();return file;}};ServiceDocumentStore.restoreArchive(isolated,NativeBackupRestoreProbe.inventory(prepared.manifest),new FileInputStream(prepared.documents));File restored=new File(directory,"service-documents");if(!newDocs.delete()||!restored.renameTo(newDocs))throw new IOException("Δεν προετοιμάστηκαν όλα τα ιδιωτικά αρχεία ανάκτησης.");}
                JSONObject protection=password==null?BackupProtection.snapshot(c):BackupProtection.candidate(password);if(protection.length()==0)throw new IOException("Χρειάζεται φορητός κωδικός για το νέο backup ανάκτησης.");
                JSONObject settings=root.getJSONObject("settings");settings.put("workerUrl",root.getJSONObject("nativeRecovery").getString("realm"));
                JSONObject value=new JSONObject().put("id",id).put("createdAt",System.currentTimeMillis()).put("backupCreatedAt",root.getString("createdAt")).put("fileName",BackupManager.queryDisplayName(c,uri)).put("manifest",prepared.manifest).put("recovery",root.getJSONObject("nativeRecovery")).put("settings",settings).put("newProtection",protection).put("accounts",accounts).put("proof",proof);
                SealedLocalState.write(c,PREVIEW,ALIAS,value);return publicPreview(value);
            }
        }finally{running.set(false);}
    }
    private static JSONObject publicPreview(JSONObject value)throws Exception{return new JSONObject().put("previewId",value.getString("id")).put("fileName",value.getString("fileName")).put("backupCreatedAt",value.getString("backupCreatedAt")).put("accounts",value.getJSONArray("accounts")).put("tables",value.getJSONObject("manifest").getJSONArray("tables")).put("documents",value.getJSONObject("manifest").getJSONArray("objects").length()).put("restoreVerified",value.getJSONObject("proof").optBoolean("restoreVerified")).put("documentsVerified",value.getJSONObject("proof").optBoolean("documentsVerified"));}
    public static JSONObject status(Context c)throws Exception{
        JSONObject result=new JSONObject(prefs(c).getString(STATUS,"{}"));result.put("busy",running.get()).put("blocked",NativeColdRuntime.blocked(c)).put("coldPhase",NativeColdRuntime.core(c).state().optString("phase"));
        if(!running.get()&&!NativeColdRuntime.blocked(c)){try(FleetDataStore store=new FleetDataStore(c)){JSONObject state=NativePrimaryState.read(store.getReadableDatabase());result.put("phase",state.optString("phase","cloud"));}JSONObject identity=NativeIdentity.read(c);if(identity.length()>0)result.put("fingerprint",BusinessRuntime.sha256(identity.getString("publicKey").getBytes("UTF-8"))).put("notBefore",identity.optLong("recoveryNotBefore",0));}
        return result;
    }
    private static JSONObject cloud(Context c,JSONObject identity,String action,JSONObject body)throws Exception{return FleetHttp.sendJson(identity.getString("realm")+"/api/primary/recovery/"+action,"POST",body,SyncService.serverHeaders());}
    public static JSONObject prepare(Context c,JSONObject input)throws Exception{
        if(!input.optBoolean("accountsReviewed")||!input.optBoolean("backupCodeSaved")||!input.optBoolean("replaceConfirmed"))throw new IOException("Έλεγξε τους λογαριασμούς και επιβεβαίωσε το backup και την αντικατάσταση πριν συνεχίσεις.");
        if(!running.compareAndSet(false,true))throw new IOException("Εκτελείται ήδη ανάκτηση.");boolean locked=false;
        try(FleetDataStore store=new FleetDataStore(c)){
            JSONObject preview=SealedLocalState.read(c,PREVIEW,ALIAS);if(!preview.optString("id").equals(input.getString("previewId"))||System.currentTimeMillis()-preview.optLong("createdAt")>86400000)throw new IOException("Η προεπισκόπηση άλλαξε ή έληξε. Επίλεξε ξανά το backup.");
            String ownerId=input.getString("ownerId");boolean eligible=false;JSONArray accounts=preview.getJSONArray("accounts");for(int i=0;i<accounts.length();i++){JSONObject a=accounts.getJSONObject(i);if(a.optString("id").equals(ownerId)&&a.optString("role").equals("owner")&&a.optInt("active")==1&&a.optInt("login_enabled")==1&&a.isNull("deleted_at"))eligible=true;}if(!eligible)throw new IOException("Επίλεξε ενεργό ιδιοκτήτη από το ελεγμένο backup.");
            stage(c,"Αναμονή ολοκλήρωσης τρεχουσών εργασιών");NativeWorkGate.exclusive(new NativeWorkGate.Check(){public void check()throws Exception{stage(c,"Αναμονή ολοκλήρωσης τρεχουσών εργασιών");}});locked=true;
            JSONObject pending=NativeIdentity.pendingRecovery(c);if(!pending.optString("id").equals(preview.getString("id"))){
                stage(c,"Τοπικό αντίγραφο πριν από αντικατάσταση");JSONObject before=BackupJobs.createLocalAutomatic(c,store);if(!BackupJobs.localReady(c,before)||before.optInt("missingDocuments",-1)!=0)throw new IOException("Δεν ολοκληρώθηκε το αντίγραφο των τωρινών δεδομένων.");
                pending=new JSONObject().put("id",preview.getString("id")).put("identity",NativeIdentity.recoveryCandidate(preview.getJSONObject("recovery"),ownerId)).put("manifest",preview.getJSONObject("manifest")).put("settings",preview.getJSONObject("settings")).put("oldIdentity",NativeIdentity.read(c)).put("oldSettings",BackupManager.settingsPayload(c)).put("oldProtection",BackupProtection.snapshot(c)).put("newProtection",preview.getJSONObject("newProtection")).put("oldRecoveryPending",prefs(c).getBoolean("native_recovery_pending",false)).put("oldRecoveryTransaction",prefs(c).getString("native_recovery_transaction","")).put("beforeBackupId",before.getString("id"));NativeIdentity.pendingRecovery(c,pending);
            }
            JSONObject identity=pending.getJSONObject("identity");if(!identity.getString("ownerId").equals(ownerId))throw new IOException("Η προηγούμενη προετοιμασία χρησιμοποιεί άλλο επιλεγμένο ιδιοκτήτη. Άνοιξε ξανά το backup για νέα επιλογή.");
            NativeDatabaseSnapshot.verifyReadOnly(new File(NativeColdRuntime.core(c).directory(preview.getString("id")),"new-databases/"+NativeColdRestore.DATABASE_NAME),preview.getJSONObject("manifest"));
            stage(c,"Ασφαλής δέσμευση της νέας ταυτότητας Server");JSONObject reservation=cloud(c,identity,"prepare",new JSONObject().put("recoveryToken",identity.getString("recoveryProof")).put("generation",identity.getString("generation")).put("publicKey",identity.getString("publicKey")).put("publicSalt",identity.getString("publicSalt")).put("newRecoveryHash",BusinessRuntime.sha256(identity.getString("recoveryToken").getBytes("UTF-8"))).put("contentHash",pending.getJSONObject("manifest").getString("sha256")).put("restoreVerified",true).put("documentsVerified",true).put("accountsReviewed",true));
            if(!reservation.optBoolean("reserved")||!reservation.optString("generation").equals(identity.getString("generation"))||!reservation.optString("reservation").matches("[a-f0-9-]{36}"))throw new IOException("Δεν επιβεβαιώθηκε η δέσμευση ανάκτησης.");
            identity.put("recoveryReservation",reservation.getString("reservation")).put("recoveryNotBefore",reservation.getLong("notBefore"));NativeIdentity.pendingRecovery(c,pending);
            NativeColdRuntime.core(c).arm(pending.getString("id"),pending.getJSONObject("manifest"),NativeColdRuntime.pendingHash(pending));NativePrimaryService.get(c).pause();stage(c,"Έτοιμη η ανάκτηση· απαιτείται επανεκκίνηση Server");return new JSONObject().put("restartRequired",true).put("restoreVerified",true).put("documentsVerified",true);
        }finally{if(locked)NativeWorkGate.release();running.set(false);}
    }
    public static JSONObject finish(Context c)throws Exception{
        if(!running.compareAndSet(false,true))throw new IOException("Εκτελείται ήδη ανάκτηση.");boolean locked=false;
        try(FleetDataStore store=new FleetDataStore(c)){
            NativeWorkGate.exclusive(new NativeWorkGate.Check(){public void check()throws Exception{stage(c,"Αναμονή ασφαλούς ολοκλήρωσης εργασιών");}});locked=true;JSONObject state=NativePrimaryState.read(store.getReadableDatabase()),identity=NativeIdentity.read(c);
            if(!state.optString("phase").equals("recovering")||!state.optString("generation").equals(identity.optString("generation")))throw new IOException("Δεν υπάρχει εγκατεστημένη ανάκτηση προς ολοκλήρωση.");
            if(System.currentTimeMillis()<identity.getLong("recoveryNotBefore"))throw new IOException("Περίμενε "+Math.max(1,(identity.getLong("recoveryNotBefore")-System.currentTimeMillis()+999)/1000)+" δευτερόλεπτα για την ασφαλή λήξη της παλιάς σύνδεσης.");
            stage(c,"Προετοιμασία συμβατού σχήματος ανάκτησης");NativePrimaryService.get(c).initializeCandidate(identity);
            JSONObject evidence=identity.optJSONObject("recoveryEvidence"),job=null;
            if(evidence!=null)try{JSONObject saved=BackupJobs.load(c,evidence.getString("backupJobId"));if(saved.getString("dataSha256").equals(evidence.getString("manifestSha256"))&&saved.getJSONObject("nativeProof").optBoolean("restoreVerified")&&BackupJobs.localReady(c,saved))job=saved;}catch(Exception missing){}
            if(job==null){stage(c,"Νέο φορητό backup και πλήρης πραγματική δοκιμή ανάκτησης");job=BackupJobs.createLocalAutomatic(c,store);JSONObject proof=job.getJSONObject("nativeProof");if(!job.optBoolean("portable")||!proof.optBoolean("restoreVerified")||!proof.optBoolean("documentsVerified")||!BackupJobs.localReady(c,job))throw new IOException("Δεν επαληθεύτηκε το νέο πλήρες backup ανάκτησης.");evidence=new JSONObject().put("backupJobId",job.getString("id")).put("manifestSha256",job.getString("dataSha256"));identity.put("recoveryEvidence",evidence);NativeIdentity.save(c,identity);}
            stage(c,"Οριστική αλλαγή κύριου Server");JSONObject result=cloud(c,identity,"finish",new JSONObject().put("recoveryToken",identity.getString("recoveryProof")).put("generation",identity.getString("generation")).put("reservation",identity.getString("recoveryReservation")).put("newBackupVerified",true).put("newBackupHash",evidence.getString("manifestSha256")));
            if(!result.optBoolean("active")||!result.optString("generation").equals(identity.getString("generation"))||!result.optString("contentHash").equals(state.getString("data_hash"))||result.optString("eventSigningKey").length()<32)throw new IOException("Δεν επιβεβαιώθηκε η τελική αλλαγή Server. Συνέχισε την ίδια ανάκτηση.");
            identity.put("eventSigningKey",result.getString("eventSigningKey"));NativeIdentity.save(c,identity);new NativeMigrationTransport(identity,ServerConfig.SERVER_KEY).signedProbe(identity);
            OrdexaSync.clearForRecovery(c);
            store.getWritableDatabase().execSQL("UPDATE native_primary_state SET phase='active',proof_sha=? WHERE id=1 AND generation=? AND phase='recovering'",new Object[]{job.getJSONObject("nativeProof").getString("databaseSha256"),identity.getString("generation")});
            identity.remove("recoveryProof");try{NativeIdentity.save(c,identity);}catch(Exception retainedRetiredProof){}prefs(c).edit().putBoolean("native_recovery_pending",false).putString(STATUS,new JSONObject().put("stage","Η ανάκτηση ολοκληρώθηκε· χρειάζεται νέα σύνδεση χρηστών και Ordexa").put("updatedAt",System.currentTimeMillis()).toString()).commit();NativePrimaryService.get(c).start();return new JSONObject().put("active",true).put("restoreVerified",true).put("documentsVerified",true).put("newBackupVerified",true).put("connected",NativePrimaryService.get(c).available());
        }finally{if(locked)NativeWorkGate.release();running.set(false);}
    }
}
